// Get Form Values
const origin = $json["Origin"];
const destination = $json["Destination"];
const startDate = new Date($json["Start Date"]);
const endDate = new Date($json["End Date"]);

const minBudgetRaw = $json["Minimum Budget"];
const maxBudgetRaw = $json["Maximum Budget"];

// Remove currency symbols & commas
const minBudget = parseFloat(String(minBudgetRaw).replace(/[^0-9.]/g, ""));
const maxBudget = parseFloat(String(maxBudgetRaw).replace(/[^0-9.]/g, ""));

// Calculate Trip Duration

const diffTime = Math.abs(endDate - startDate);
const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

let trip_duration;

if (diffDays <= 3) {
  trip_duration = "short";
} else if (diffDays <= 7) {
  trip_duration = "medium";
} else {
  trip_duration = "long";
}

// Return Enriched Context

return [
  {
    json: {
      ...$json,
      total_trip_days: diffDays,
      trip_duration
    }
  }
];

const markdown = $json.markdown;

// helper function
function extractBetween(text, start, end) {
  const regex = new RegExp(`${start}([\\s\\S]*?)${end}`);
  const match = text.match(regex);
  return match ? match[1].trim() : "";
}

// Extract major sections
const route = extractBetween(markdown, "## Route", "## Travel Dates");
const dates = extractBetween(markdown, "## Travel Dates", "## Travel Style");
const style = extractBetween(markdown, "## Travel Style", "---");
const recommended = extractBetween(markdown, "## Recommended Plan", "## Validation Check");
const validationBlock = extractBetween(markdown, "## Validation Check", "Enjoy your journey");

// Extract plan bullets
function extractBullet(text, title) {
  const regex = new RegExp(`\\*\\*${title}:\\*\\*[\\s\\n]*-?([\\s\\S]*?)(\\n\\n|$)`);
  const match = text.match(regex);
  return match ? match[1].trim() : "";
}

const travelWindow = extractBullet(recommended, "Travel Window");
const stayArea = extractBullet(recommended, "Recommended Stay Area");
const activity = extractBullet(recommended, "Must-Do Activity");
const caution = extractBullet(recommended, "Caution");
const vibe = extractBullet(recommended, "Overall Travel Vibe");

// Extract validation decision
const decisionMatch = validationBlock.match(/Decision:\s*(YES|NO)/i);
const justificationMatch = validationBlock.match(/Justification:\s*([^\n]+)/i);

const decision = decisionMatch ? decisionMatch[1].toUpperCase() : "";
const justification = justificationMatch ? justificationMatch[1].trim() : "";

return [
{
json: {

route: route.replace(/\*\*/g,"").trim(),
travel_dates: dates.replace(/\*\*/g,"").trim(),
travel_style: style.replace(/\*\*/g,"").trim(),

travel_window: travelWindow,
recommended_stay_area: stayArea,
must_do_activity: activity,
caution: caution,
travel_vibe: vibe,

decision: decision,
justification: justification,

full_markdown: markdown
}
}
];

// Extract the generated travel plan
const travelPlan =
  $node["Travel Planning Agent"].json.output?.[0]?.content?.[0]?.text || "Travel plan not available.";

// Extract validation result
const validation =
  $node["Travel Plan Validator Agent"].json.output?.[0]?.content?.[0]?.text || "Validation unavailable.";

// Extract form values
const destination = $node["Context Enrichment for LLM"].json["Destination"];
const origin = $node["Context Enrichment for LLM"].json["Origin"];
const startDate = $node["Context Enrichment for LLM"].json["Start Date"];
const endDate = $node["Context Enrichment for LLM"].json["End Date"];
const tripDays = $node["Context Enrichment for LLM"].json["total_trip_days"];
const style = $node["Context Enrichment for LLM"].json["What is your Travel Style Preference?"];

// Markdown formatted report
const markdownReport = `
# ✈️ Smart Travel Plan

## Route
**${origin} → ${destination}**

## Travel Dates
**${startDate} → ${endDate} (${tripDays} days)**

## Travel Style
**${style}**

---

## Recommended Plan

${travelPlan}

---

## Validation Check

${validation}

---

🌍 **Enjoy your journey and travel safely!**
`;

return [
  {
    json: {
      markdown: markdownReport
    }
  }
];
